create sequence if not exists supplier_invoice_number_seq;
create table supplier_invoices(id bigint generated by default as identity primary key,tenant_id bigint not null references tenants(id),company_id bigint not null references companies(id),branch_id bigint not null references branches(id),supplier_id bigint not null references suppliers(id),purchase_order_id bigint not null references purchase_orders(id),goods_receipt_id bigint not null references goods_receipts(id),invoice_number varchar(64) not null,invoice_date date not null,status varchar(16) not null default 'DRAFT',subtotal numeric(18,2) not null default 0,total numeric(18,2) not null default 0,payable_posting_reference varchar(160),notes varchar(2000),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),version bigint not null default 0,unique(tenant_id,invoice_number),check(status in ('DRAFT','ISSUED','CANCELLED')));
create table supplier_invoice_lines(id bigint generated by default as identity primary key,tenant_id bigint not null references tenants(id),invoice_id bigint not null references supplier_invoices(id) on delete cascade,goods_receipt_line_id bigint not null references goods_receipt_lines(id),product_id bigint not null references products(id),quantity numeric(18,3) not null,unit_price numeric(18,2) not null,line_total numeric(18,2) not null,check(quantity>0 and unit_price>=0 and line_total>=0));
